message.content:
{
  "summary": "这份数据提供了多个批次的测试结果，包括良率、失败项目、异常集中、版本比较和数据质量问题。通过这些信息，我们可以分析各批次的良率差异、失败最多的测试项目、异常集中情况、版本变化以及数据质量问题。",
  "findings": [
    {
      "claim": "各运行各批次的良率，以及 yield_all 与 yield_complete_only 两个分母为何不同（incomplete 芯片）",
      "evidence": [
        "yield_by_lot[1].yield_all",
        "yield_by_lot[1].yield_complete_only",
        "yield_by_lot[1].incomplete"
      ]
    },
    {
      "claim": "失败最多的测试项目",
      "evidence": [
        "top_items[0].test_item",
        "top_items[0].final_fail_rate"
      ]
    },
    {
      "claim": "concentration_wafer 中的异常集中",
      "evidence": [
        "concentration_wafer[0].wafer_id",
        "concentration_wafer[0].test_item",
        "concentration_wafer[0].fail_rate"
      ]
    },
    {
      "claim": "version_compare 与 run_diff 显示的变化",
      "evidence": [
        "version_compare.a.programs.R1",
        "version_compare.b.programs.R2",
        "run_diff.counts.new_failure",
        "run_diff.counts.fixed"
      ]
    },
    {
      "claim": "quality_counts 中会影响结论的数据质量问题",
      "evidence": [
        "quality_counts.unit_converted",
        "quality_counts.limit_mismatch",
        "quality_counts.incomplete_chip",
        "quality_counts.duplicate_row",
        "quality_counts.missing_value",
        "quality_counts.conflicting_measurement",
        "quality_counts.status_inconsistent",
        "quality_counts.implausible_value",
        "quality_counts.empty_file",
        "quality_counts.missing_status"
      ]
    }
  ],
  "uncertainties": [
    "记录口径假设：测试记录通过率 = PASS 行数 / (PASS + FAIL 行数)",
    "样本量：数据量有限，可能无法代表整体情况",
    "数据质量：存在一些质量问题，如重复行、缺失值等，可能影响分析结果"
  ],
  "next_checks": [
    "人工确认各批次的良率差异是否合理",
    "验证失败最多的测试项目是否需要进一步分析",
    "检查异常集中情况是否需要采取措施",
    "确认版本变化是否对测试结果有影响",
    "审查数据质量问题，确保数据的准确性和完整性"
  ]
}
